`timescale 1 ns / 1 ps

module AESL_deadlock_report_unit #( parameter PROC_NUM = 4 ) (
    input dl_reset,
    input dl_clock,
    input [PROC_NUM - 1:0] dl_in_vec,
    input ap_done_reg_0,
    input ap_done_reg_1,
    output dl_detect_out,
    output reg [PROC_NUM - 1:0] origin,
    output token_clear);
   
    // FSM states
    localparam ST_IDLE = 3'b000;
    localparam ST_FILTER_FAKE = 3'b001;
    localparam ST_DL_DETECTED = 3'b010;
    localparam ST_DL_REPORT = 3'b100;

    reg find_df_deadlock;
    reg [2:0] CS_fsm;
    reg [2:0] NS_fsm;
    reg [PROC_NUM - 1:0] dl_detect_reg;
    reg [PROC_NUM - 1:0] dl_done_reg;
    reg [PROC_NUM - 1:0] origin_reg;
    reg [PROC_NUM - 1:0] dl_in_vec_reg;
    reg [31:0] dl_keep_cnt;
    reg stop_report_path;
    reg [PROC_NUM - 1:0] reported_proc;
    integer i;
    integer fp;

    always @ (negedge dl_reset or posedge dl_clock) begin
        if (~dl_reset) begin
            reported_proc <= 'b0;
        end
        else if (CS_fsm == ST_DL_REPORT) begin
            reported_proc <= reported_proc | dl_in_vec;
        end
        else if (CS_fsm == ST_DL_DETECTED) begin
            reported_proc <= 'b0;
        end
    end

    always @ (negedge dl_reset or posedge dl_clock) begin
        if (~dl_reset) begin
            stop_report_path <= 1'b0;
        end
        else if (CS_fsm == ST_DL_REPORT && (|(dl_in_vec & reported_proc))) begin
            stop_report_path <= 1'b1;
        end
        else if (CS_fsm == ST_IDLE) begin
            stop_report_path <= 1'b0;
        end
    end

    // FSM State machine
    always @ (negedge dl_reset or posedge dl_clock) begin
        if (~dl_reset) begin
            CS_fsm <= ST_IDLE;
        end
        else begin
            CS_fsm <= NS_fsm;
        end
    end

    always @ (CS_fsm or dl_in_vec or dl_detect_reg or dl_done_reg or dl_in_vec or origin_reg or dl_keep_cnt) begin
        case (CS_fsm)
            ST_IDLE : begin
                if (|dl_in_vec) begin
                    NS_fsm = ST_FILTER_FAKE;
                end
                else begin
                    NS_fsm = ST_IDLE;
                end
            end
            ST_FILTER_FAKE: begin
                if (dl_keep_cnt >= 32'd1000) begin
                    NS_fsm = ST_DL_DETECTED;
                end
                else if (dl_detect_reg != (dl_detect_reg & dl_in_vec)) begin
                    NS_fsm = ST_IDLE;
                end
                else begin
                    NS_fsm = ST_FILTER_FAKE;
                end
            end
            ST_DL_DETECTED: begin
                // has unreported deadlock cycle
                if ((dl_detect_reg != dl_done_reg) && stop_report_path == 1'b0) begin
                    NS_fsm = ST_DL_REPORT;
                end
                else begin
                    NS_fsm = ST_DL_DETECTED;
                end
            end
            ST_DL_REPORT: begin
                if (|(dl_in_vec & origin_reg)) begin
                    NS_fsm = ST_DL_DETECTED;
                end
                // avoid report deadlock ring.
                else if (|(dl_in_vec & reported_proc)) begin
                    NS_fsm = ST_DL_DETECTED;
                end
                else begin
                    NS_fsm = ST_DL_REPORT;
                end
            end
            default: NS_fsm = ST_IDLE;
        endcase
    end

    // dl_detect_reg record the procs that first detect deadlock
    always @ (negedge dl_reset or posedge dl_clock) begin
        if (~dl_reset) begin
            dl_detect_reg <= 'b0;
        end
        else begin
            if (CS_fsm == ST_IDLE) begin
                dl_detect_reg <= dl_in_vec;
            end
        end
    end

    always @ (negedge dl_reset or posedge dl_clock) begin
        if (~dl_reset) begin
            dl_keep_cnt <= 32'h0;
        end
        else begin
            if (CS_fsm == ST_FILTER_FAKE && (dl_detect_reg == (dl_detect_reg & dl_in_vec))) begin
                dl_keep_cnt <= dl_keep_cnt + 32'h1;
            end
            else if (CS_fsm == ST_FILTER_FAKE && (dl_detect_reg != (dl_detect_reg & dl_in_vec))) begin
                dl_keep_cnt <= 32'h0;
            end
        end
    end

    // dl_detect_out keeps in high after deadlock detected
    assign dl_detect_out = (|dl_detect_reg) && (CS_fsm == ST_DL_DETECTED || CS_fsm == ST_DL_REPORT);

    // dl_done_reg record the cycles has been reported
    always @ (negedge dl_reset or posedge dl_clock) begin
        if (~dl_reset) begin
            dl_done_reg <= 'b0;
        end
        else begin
            if ((CS_fsm == ST_DL_REPORT) && (|(dl_in_vec & dl_detect_reg) == 'b1)) begin
                dl_done_reg <= dl_done_reg | dl_in_vec;
            end
        end
    end

    // clear token once a cycle is done
    assign token_clear = (CS_fsm == ST_DL_REPORT) ? ((|(dl_in_vec & origin_reg)) ? 'b1 : 'b0) : 'b0;

    // origin_reg record the current cycle start id
    always @ (negedge dl_reset or posedge dl_clock) begin
        if (~dl_reset) begin
            origin_reg <= 'b0;
        end
        else begin
            if (CS_fsm == ST_DL_DETECTED) begin
                origin_reg <= origin;
            end
        end
    end
   
    // origin will be valid for only one cycle
    wire [PROC_NUM*PROC_NUM - 1:0] origin_tmp;
    assign origin_tmp[PROC_NUM - 1:0] = (dl_detect_reg[0] & ~dl_done_reg[0]) ? 'b1 : 'b0;
    genvar j;
    generate
    for(j = 1;j < PROC_NUM;j = j + 1) begin: F1
        assign origin_tmp[j*PROC_NUM +: PROC_NUM] = (dl_detect_reg[j] & ~dl_done_reg[j]) ? ('b1 << j) : origin_tmp[(j - 1)*PROC_NUM +: PROC_NUM];
    end
    endgenerate
    always @ (CS_fsm or origin_tmp) begin
        if (CS_fsm == ST_DL_DETECTED) begin
            origin = origin_tmp[(PROC_NUM - 1)*PROC_NUM +: PROC_NUM];
        end
        else begin
            origin = 'b0;
        end
    end

    
    // dl_in_vec_reg record the current cycle dl_in_vec
    always @ (negedge dl_reset or posedge dl_clock) begin
        if (~dl_reset) begin
            dl_in_vec_reg <= 'b0;
        end
        else begin
            if (CS_fsm == ST_DL_DETECTED) begin
                dl_in_vec_reg <= origin;
            end
            else if (CS_fsm == ST_DL_REPORT) begin
                dl_in_vec_reg <= dl_in_vec;
            end
        end
    end
    
    // find_df_deadlock to report the deadlock
    always @ (negedge dl_reset or posedge dl_clock) begin
        if (~dl_reset) begin
            find_df_deadlock <= 1'b0;
        end
        else begin
            if (CS_fsm == ST_DL_DETECTED && ((dl_detect_reg == dl_done_reg) || (stop_report_path == 1'b1))) begin
                find_df_deadlock <= 1'b1;
            end
            else if (CS_fsm == ST_IDLE) begin
                find_df_deadlock <= 1'b0;
            end
        end
    end
    
    // get the first valid proc index in dl vector
    function integer proc_index(input [PROC_NUM - 1:0] dl_vec);
        begin
            proc_index = 0;
            for (i = 0; i < PROC_NUM; i = i + 1) begin
                if (dl_vec[i]) begin
                    proc_index = i;
                end
            end
        end
    endfunction

    // get the proc path based on dl vector
    function [984:0] proc_path(input [PROC_NUM - 1:0] dl_vec);
        integer index;
        begin
            index = proc_index(dl_vec);
            case (index)
                0 : begin
                    proc_path = "top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.entry_proc_U0";
                end
                1 : begin
                    proc_path = "top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0";
                end
                2 : begin
                    proc_path = "top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.load_input_U0";
                end
                3 : begin
                    proc_path = "top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.conv_2_13_13_3_3_2_11_11_1_1_5_1_5_5_2_3_U0";
                end
                4 : begin
                    proc_path = "top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.out_conv2mem_2_13_13_3_3_2_11_11_1_162_1_1_5_5_2_3_U0";
                end
                default : begin
                    proc_path = "unknown";
                end
            endcase
        end
    endfunction

    // print the headlines of deadlock detection
    task print_dl_head;
        begin
            $display("\n//////////////////////////////////////////////////////////////////////////////");
            $display("// ERROR!!! DEADLOCK DETECTED at %0t ns! SIMULATION WILL BE STOPPED! //", $time);
            $display("//////////////////////////////////////////////////////////////////////////////");
            fp = $fopen("deadlock_db.dat", "w");
        end
    endtask

    // print the start of a cycle
    task print_cycle_start(input reg [984:0] proc_path, input integer cycle_id);
        begin
            $display("/////////////////////////");
            $display("// Dependence cycle %0d:", cycle_id);
            $display("// (1): Process: %0s", proc_path);
            $fdisplay(fp, "Dependence_Cycle_ID %0d", cycle_id);
            $fdisplay(fp, "Dependence_Process_ID 1");
            $fdisplay(fp, "Dependence_Process_path %0s", proc_path);
        end
    endtask

    // print the end of deadlock detection
    task print_dl_end(input integer num, input integer record_time);
        begin
            $display("////////////////////////////////////////////////////////////////////////");
            $display("// Totally %0d cycles detected!", num);
            $display("////////////////////////////////////////////////////////////////////////");
            $fdisplay(fp, "Dependence_Cycle_Number %0d", num);
            $fclose(fp);
        end
    endtask

    // print one proc component in the cycle
    task print_cycle_proc_comp(input reg [984:0] proc_path, input integer cycle_comp_id);
        begin
            $display("// (%0d): Process: %0s", cycle_comp_id, proc_path);
            $fdisplay(fp, "Dependence_Process_ID %0d", cycle_comp_id);
            $fdisplay(fp, "Dependence_Process_path %0s", proc_path);
        end
    endtask

    // print one channel component in the cycle
    task print_cycle_chan_comp(input [PROC_NUM - 1:0] dl_vec1, input [PROC_NUM - 1:0] dl_vec2);
        reg [648:0] chan_path;
        integer index1;
        integer index2;
        begin
            index1 = proc_index(dl_vec1);
            index2 = proc_index(dl_vec2);
            case (index1)
                0 : begin // for proc 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.entry_proc_U0'
                    case(index2)
                    4: begin //  for dep proc 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.out_conv2mem_2_13_13_3_3_2_11_11_1_162_1_1_5_5_2_3_U0'
// for dep channel 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.memory_c_U' info is :
// blk sig is {~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.entry_proc_U0.memory_c_blk_n data_FIFO}
                        if ((~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.entry_proc_U0.memory_c_blk_n)) begin
                            if (~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.memory_c_U.if_empty_n) begin
                                $display("//      Blocked by empty input FIFO 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.memory_c_U' written by process 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.out_conv2mem_2_13_13_3_3_2_11_11_1_162_1_1_5_5_2_3_U0'");
                                $fdisplay(fp, "Dependence_Channel_path top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.memory_c_U");
                                $fdisplay(fp, "Dependence_Channel_status EMPTY");
                            end
                            else if (~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.memory_c_U.if_full_n) begin
                                $display("//      Blocked by full output FIFO 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.memory_c_U' read by process 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.out_conv2mem_2_13_13_3_3_2_11_11_1_162_1_1_5_5_2_3_U0'");
                                $fdisplay(fp, "Dependence_Channel_path top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.memory_c_U");
                                $fdisplay(fp, "Dependence_Channel_status FULL");
                            end
                        end
                    end
                    1: begin //  for dep proc 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0'
// for dep channel '' info is :
// blk sig is {{AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_entry_proc_U0_ap_ready & AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.entry_proc_U0.ap_idle & ~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0_ap_ready} input_sync}
                        if ((AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_entry_proc_U0_ap_ready & AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.entry_proc_U0.ap_idle & ~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0_ap_ready)) begin
                            $display("//      Blocked by input sync logic with process : 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0'");
                        end
                    end
                    2: begin //  for dep proc 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.load_input_U0'
// for dep channel '' info is :
// blk sig is {{AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_entry_proc_U0_ap_ready & AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.entry_proc_U0.ap_idle & ~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_load_input_U0_ap_ready} input_sync}
                        if ((AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_entry_proc_U0_ap_ready & AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.entry_proc_U0.ap_idle & ~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_load_input_U0_ap_ready)) begin
                            $display("//      Blocked by input sync logic with process : 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.load_input_U0'");
                        end
                    end
                    endcase
                end
                1 : begin // for proc 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0'
                    case(index2)
                    3: begin //  for dep proc 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.conv_2_13_13_3_3_2_11_11_1_1_5_1_5_5_2_3_U0'
// for dep channel 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.filter2conv_U' info is :
// blk sig is {~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0.filter2conv_blk_n data_FIFO}
                        if ((~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0.filter2conv_blk_n)) begin
                            if (~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.filter2conv_U.if_empty_n) begin
                                $display("//      Blocked by empty input FIFO 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.filter2conv_U' written by process 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.conv_2_13_13_3_3_2_11_11_1_1_5_1_5_5_2_3_U0'");
                                $fdisplay(fp, "Dependence_Channel_path top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.filter2conv_U");
                                $fdisplay(fp, "Dependence_Channel_status EMPTY");
                            end
                            else if (~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.filter2conv_U.if_full_n) begin
                                $display("//      Blocked by full output FIFO 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.filter2conv_U' read by process 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.conv_2_13_13_3_3_2_11_11_1_1_5_1_5_5_2_3_U0'");
                                $fdisplay(fp, "Dependence_Channel_path top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.filter2conv_U");
                                $fdisplay(fp, "Dependence_Channel_status FULL");
                            end
                        end
                    end
                    0: begin //  for dep proc 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.entry_proc_U0'
// for dep channel '' info is :
// blk sig is {{AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0_ap_ready & AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0.ap_idle & ~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_entry_proc_U0_ap_ready} input_sync}
                        if ((AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0_ap_ready & AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0.ap_idle & ~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_entry_proc_U0_ap_ready)) begin
                            $display("//      Blocked by input sync logic with process : 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.entry_proc_U0'");
                        end
                    end
                    2: begin //  for dep proc 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.load_input_U0'
// for dep channel '' info is :
// blk sig is {{AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0_ap_ready & AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0.ap_idle & ~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_load_input_U0_ap_ready} input_sync}
                        if ((AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0_ap_ready & AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.dataflow_in_loop_VITIS_LOOP_92_1_1_Loop_VITIS_LOOP_99_2_proc_U0.ap_idle & ~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.ap_sync_load_input_U0_ap_ready)) begin
                            $display("//      Blocked by input sync logic with process : 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.load_input_U0'");
                        end
                    end
                    endcase
                end
                2 : begin // for proc 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.load_input_U0'
                    case(index2)
                    4: begin //  for dep proc 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.out_conv2mem_2_13_13_3_3_2_11_11_1_162_1_1_5_5_2_3_U0'
// for dep channel 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.img_0_c_U' info is :
// blk sig is {~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.load_input_U0.img_0_c_blk_n data_FIFO}
                        if ((~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.load_input_U0.img_0_c_blk_n)) begin
                            if (~AESL_inst_top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.img_0_c_U.if_empty_n) begin
                                $display("//      Blocked by empty input FIFO 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.img_0_c_U' written by process 'top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.out_conv2mem_2_13_13_3_3_2_11_11_1_162_1_1_5_5_2_3_U0'");
                                $fdisplay(fp, "Dependence_Channel_path top_wrapper.dataflow_in_loop_VITIS_LOOP_92_1_1_U0.img_0_c_U");
                                $fdisplay(fp, "Dependence_Channel_status EMPTY");
                            end
